begin;

create extension if not exists pgcrypto;

create table if not exists public.step_obras_costs (
  id bigserial primary key,
  row_key text not null unique,
  item_id text references public.step_obras_items(id) on delete set null,
  setor text,
  cotacao text,
  data_cotacao date,
  pedido text,
  data_pedido date,
  fornecedor text,
  produto text,
  quantidade numeric(14,3) default 0,
  valor numeric(14,2) default 0,
  origem text,
  status_compra text default 'Não informado',
  disciplina text,
  observacao text,
  source text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_step_obras_costs_item_id on public.step_obras_costs(item_id);
create index if not exists idx_step_obras_costs_status on public.step_obras_costs(status_compra);
create index if not exists idx_step_obras_costs_setor on public.step_obras_costs(setor);
create index if not exists idx_step_obras_costs_pedido on public.step_obras_costs(pedido);

alter table public.step_obras_costs enable row level security;

drop policy if exists "step_obras_costs_select" on public.step_obras_costs;
create policy "step_obras_costs_select"
on public.step_obras_costs for select
to anon, authenticated
using (true);

