insert into public.step_obras_items
(id, area, title, status, progress, owner, priority, next_action, notes, ordem, ativo, metadata)
select
  id,
  area,
  title,
  status::public.step_obra_status,
  progress,
  owner,
  priority::public.step_prioridade,
  next_action,
  notes,
  ordem,
  true,
  coalesce(metadata, '{}'::jsonb)
from src
on conflict (id) do update set
  area = excluded.area,
  title = excluded.title,
  status = excluded.status,
  progress = excluded.progress,
  owner = excluded.owner,
  priority = excluded.priority,
  next_action = excluded.next_action,
  notes = excluded.notes,
  ordem = excluded.ordem,
  ativo = true,
  metadata = coalesce(public.step_obras_items.metadata, '{}'::jsonb) || excluded.metadata;

