-- ---------------------------------------------------------
-- 3) Recalcula custos por item no cadastro principal
-- ---------------------------------------------------------
update public.step_obras_items
set
  cost = 0,
  custo_comprado = 0,
  status_compra = 'Não informado'::public.step_status_compra
where ativo = true;

with rollup as (
  select
    item_id,
    sum(valor)::numeric(14,2) as total,
    sum(case when status_compra = 'Comprado' then valor else 0 end)::numeric(14,2) as comprado
  from public.step_obras_costs
  where item_id is not null
  group by item_id
),
dominante as (
  select item_id, status_compra
  from (
    select
      item_id,
      status_compra,
      sum(valor) as valor_status,
      row_number() over(partition by item_id order by sum(valor) desc, status_compra asc) as rn
    from public.step_obras_costs
    where item_id is not null
    group by item_id, status_compra
  ) ranked
  where rn = 1
)
update public.step_obras_items i
set
  cost = coalesce(r.total,0),
  custo_comprado = coalesce(r.comprado,0),
  status_compra = coalesce(d.status_compra,'Não informado')::public.step_status_compra
from rollup r
left join dominante d on d.item_id = r.item_id
where i.id = r.item_id;

